  ['How far above each point vertical raycast snapping starts. Larger values can catch bridge decks above the spline height.'] = '每个点的垂直射线投射从多高开始。数值越大越能捕捉样条高度上方的桥面。',
  ['How far grade changes are rounded along the road, turning node heights into gentle crest/sag hills. Bigger = longer hills; tight bends flatten automatically. 0 = sharp grade breaks at each node. (Terrain-draped tools ignore it.)'] = '沿道路对坡度变化做圆滑处理的程度，把节点高度变成平缓的驼峰/凹陷。数值越大坡越长；急弯处会自动变平。0 = 每个节点处坡度突变。（贴地工具会忽略此项。）',
  ['How gradually the road widens in/out of tight corners (m). Longer = gentler; independent of Transition. 0 = abrupt.'] = '进出急弯时道路加宽的过渡长度（米）。越长越平缓，与“过渡”无关。0 = 突变。',
  ['How many files are kept in the \'Recently opened files\' list.'] = '「最近打开的文件」列表中保留的文件数量。',
  ['How many laps this track has by default. Open tracks can not have more than 1 lap.'] = '此赛道默认的圈数。开放赛道不能超过 1 圈。',
