  ['If an extension is not working properly, you can start editor in safe mode (Ctrl+F11) and disable it here.'] = '若某个扩展运行异常，可用安全模式（Ctrl+F11）启动编辑器并在此禁用它。',
  ['If checked, the level scene tree will be saved at a specific interval to /settings/editor/autosaves folder in the user folder'] = '勾选后，关卡场景树会按固定间隔保存到用户目录下的 /settings/editor/autosaves 文件夹',
  ['If checked, this pathnode will be used as a split marker. Pathnode name will be shown with an asterisk.'] = '勾选后，该路径节点将作为分割标记使用，路径节点名称会带星号显示。',
  ['If enabled decals are oriented towards the next decal in the path. Overrides \'decal rotation\'.'] = '若启用，贴花将朝向路径中的下一个贴花。会覆盖“贴花旋转”。',
  ['If enabled only visible textures will be loaded in the decal texture browser.'] = '启用后，贴花贴图浏览器中只加载可见的贴图。',
  ['If enabled the marker will automatically rotate toward the player\'s vehicle'] = '启用后标记将自动朝玩家车辆旋转',
  ['If enabled the material multiplies the color value by the SimObject\'s instanceColor value.'] = '启用后，材质会将颜色值乘以该 SimObject 的 instanceColor 值。',
