  ['If enabled, position is offset from terrain origin'] = '启用后，位置将相对于地形原点偏移',
  ['If set, the mission is available as a scenario from the main menu.'] = '若设置，该任务可在主菜单中作为场景使用。',
  ['If set, the mission is not meant for release, but only for testing.'] = '若设置，该任务不用于发布，仅用于测试。',
  ['If target asset filename is different from link file name, the copy will be renamed to the latter.'] = '如果目标资源文件名与链接文件名不同，复制的文件会重命名为后者。',
  ['If the AI should use this road or not: -1 = no use, 1 = optimal, 0.5 = dirt road.'] = 'AI 是否应使用此道路：-1 = 不使用，1 = 最佳，0.5 = 土路。',
  ['If the tree view is visible'] = '如果树视图可见',
  ['If this is true, it will multiply the UI scale with system\'s DPI scale'] = '若为真，界面缩放会乘以系统的 DPI 缩放比例',
  ['If true the asset browser will create thumbnails and other data when opening a directory.'] = '若为真，资源浏览器在打开目录时会创建缩略图及其他数据。',
  ['If true the asset browser will display a color coded bar at the bottom of the asset thumbnails.'] = '若为真，资源浏览器会在资源缩略图底部显示颜色标记条。',
  ['If true the mesh will be created in front of the camera, otherwise at origin (0,0,0), when double clicking on the asset'] = '若为真，双击资源时网格会创建在相机前方，否则创建在原点 (0,0,0)',
  ['If true, AI will try to avoid collisions with other vehicles.'] = '若为真，AI 将尽量避免与其他车辆碰撞。',
  ['If true, enables a custom vehicle group to use for traffic.'] = '若为真，启用自定义车辆组用于交通。',
  ['If true, random events can happen (such as lawless drivers).'] = '若为真，可发生随机事件（例如违规驾驶者）。',
  ['If true, shows the AI trajectory debug mode.'] = '若为真，显示 AI 轨迹调试模式。',
  ['If true, the current player vehicle becomes the default vehicle for the mission.'] = '若为真，当前玩家车辆将成为该任务的默认车辆。',
  ['If true, the current player vehicle can be used for the mission.'] = '若为真，当前玩家车辆可用于该任务。',
  ['If true, the game exited properly and level was saved ok, used for autosave backups'] = '若为真，表示游戏正常退出且关卡已成功保存，用于自动保存备份',
  ['If true, the traffic lights from the map stay the same while the custom ones are used.'] = '若为真，使用自定义信号灯时地图中的信号灯保持不变。',
  ['If true, the user can set the mission time of day.'] = '若为真，用户可设置任务的时间。',
  ['If true, this mission will start with traffic enabled unless the user changes the setting.'] = '若为真，除非用户更改设置，该任务将在启用交通的情况下开始。',
